CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, email text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('ADMIN','TEACHER','STUDENT')), student_id text UNIQUE, section text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, session_version int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), last_login timestamptz);
CREATE TABLE IF NOT EXISTS courses (id uuid PRIMARY KEY, teacher_id uuid NOT NULL REFERENCES users(id), code text NOT NULL, name text NOT NULL, section text NOT NULL DEFAULT '', metadata jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS enrollments (course_id uuid REFERENCES courses(id), user_id uuid REFERENCES users(id), eligible boolean NOT NULL DEFAULT true, PRIMARY KEY(course_id,user_id));
CREATE TABLE IF NOT EXISTS questions (id uuid PRIMARY KEY, teacher_id uuid REFERENCES users(id), type text NOT NULL, prompt text NOT NULL, marks numeric NOT NULL CHECK(marks>0), options jsonb NOT NULL DEFAULT '[]', solution jsonb NOT NULL DEFAULT 'null', rubric text NOT NULL DEFAULT '', topic text NOT NULL DEFAULT '', difficulty text NOT NULL DEFAULT 'Medium', tags jsonb NOT NULL DEFAULT '[]', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS exams (id uuid PRIMARY KEY, course_id uuid NOT NULL REFERENCES courses(id), title text NOT NULL, instructions text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PUBLISHED','LIVE','PAUSED','CLOSED')), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, duration_minutes int NOT NULL CHECK(duration_minutes>0), policy jsonb NOT NULL, classroom jsonb, code_secret text NOT NULL, results_released boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at));
CREATE TABLE IF NOT EXISTS exam_questions (exam_id uuid REFERENCES exams(id), question_id uuid REFERENCES questions(id), position int NOT NULL, section text NOT NULL DEFAULT 'Section A', PRIMARY KEY(exam_id,question_id));
CREATE TABLE IF NOT EXISTS attempts (id uuid PRIMARY KEY, exam_id uuid NOT NULL REFERENCES exams(id), user_id uuid NOT NULL REFERENCES users(id), device_session_id uuid NOT NULL, status text NOT NULL DEFAULT 'ACTIVE', started_at timestamptz NOT NULL DEFAULT now(), deadline timestamptz NOT NULL, submitted_at timestamptz, last_heartbeat_at timestamptz NOT NULL DEFAULT now(), warnings int NOT NULL DEFAULT 0, revision int NOT NULL DEFAULT 0, question_order jsonb NOT NULL DEFAULT '[]', score numeric, feedback text NOT NULL DEFAULT '', UNIQUE(exam_id,user_id));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_attempt ON attempts(user_id) WHERE status='ACTIVE';
CREATE TABLE IF NOT EXISTS answers (attempt_id uuid REFERENCES attempts(id), question_id uuid REFERENCES questions(id), value jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), mark numeric, feedback text NOT NULL DEFAULT '', PRIMARY KEY(attempt_id,question_id));
CREATE TABLE IF NOT EXISTS audit_events (id uuid PRIMARY KEY, chain_key text NOT NULL, exam_id uuid REFERENCES exams(id), attempt_id uuid REFERENCES attempts(id), user_id uuid REFERENCES users(id), event_type text NOT NULL, severity text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL, previous_hash text NOT NULL, event_hash text NOT NULL, sequence bigserial UNIQUE);
CREATE INDEX IF NOT EXISTS audit_attempt_idx ON audit_events(attempt_id,sequence);
CREATE INDEX IF NOT EXISTS audit_exam_idx ON audit_events(exam_id,sequence);
CREATE INDEX IF NOT EXISTS audit_chain_idx ON audit_events(chain_key,sequence);
CREATE TABLE IF NOT EXISTS event_receipts (attempt_id uuid REFERENCES attempts(id), client_event_id uuid, PRIMARY KEY(attempt_id,client_event_id));
CREATE TABLE IF NOT EXISTS rate_limits (key text PRIMARY KEY, count int NOT NULL, resets_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS files (id uuid PRIMARY KEY, exam_id uuid REFERENCES exams(id), owner_id uuid REFERENCES users(id), name text NOT NULL, mime text NOT NULL, url text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS accommodations (exam_id uuid REFERENCES exams(id), user_id uuid REFERENCES users(id), extra_minutes int NOT NULL DEFAULT 0 CHECK(extra_minutes>=0), PRIMARY KEY(exam_id,user_id));
CREATE OR REPLACE FUNCTION deny_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit records are append-only'; END; $$;
DROP TRIGGER IF EXISTS audit_immutable ON audit_events;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION deny_audit_mutation();
